<template><form class="panel" style="width:min(100%,420px)" @submit.prevent="submit"><p class="eyebrow">Welcome back</p><h2>Sign in</h2><label>Email</label><input v-model="email" type="email" required><label>Password</label><input v-model="password" type="password" required><button class="primary" type="submit">Continue</button><p class="muted">New here? <RouterLink to="/register">Create an account</RouterLink></p></form></template>
<script setup lang="ts">import { ref } from 'vue'; import { useRouter } from 'vue-router'; import { useAuthStore } from '@/stores/auth'; const email=ref(''); const password=ref(''); const router=useRouter(); async function submit(){ await useAuthStore().login(email.value,password.value); await router.push('/') }</script>
